/* Native mGBA evidence runner. Inputs are GBA key presses; no RAM cheats.
 * Saves exported below are generated by the game's actual SAVE menu.
 * This is a smoke test, NOT a full campaign or Delta certification. */
#include <mgba/core/core.h>
#include <mgba/core/config.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
struct Symbol { uint32_t addr; char name[180]; };
static struct Symbol syms[90000];
static unsigned nsym;
static struct mCore *core;
static color_t pixels[240 * 160];
static const char *outdir;
static int failed;
static uint32_t symbol(const char *name) {
    for (unsigned i=0; i<nsym; ++i) if (!strcmp(syms[i].name,name)) return syms[i].addr;
    return 0;
}
static uint32_t rd8(uint32_t a) { return core->busRead8(core,a); }
static uint32_t rd16(uint32_t a) { return core->busRead16(core,a); }
static uint32_t rd32(uint32_t a) { return core->busRead32(core,a); }
static void frames(unsigned n, unsigned keys) {
    core->setKeys(core,keys);
    for (unsigned i=0; i<n; ++i) core->runFrame(core);
    core->setKeys(core,0);
}
static void press(unsigned keys) { frames(2,keys); frames(35,0); }
static void check(const char *name, int ok) {
    printf("CHECK %s %s\n", ok?"PASS":"FAIL",name); fflush(stdout);
    if (!ok) failed++;
}
static void snapshot(const char *name) {
    char path[1024]; snprintf(path,sizeof(path),"%s/%s.ppm",outdir,name);
    FILE *f=fopen(path,"wb"); if(!f){perror(path);exit(2);}
    fprintf(f,"P6\n240 160\n255\n");
    for(unsigned i=0;i<240*160;i++) {
        unsigned p=pixels[i];
        unsigned char rgb[3]={p&255,(p>>8)&255,(p>>16)&255};
        fwrite(rgb,1,3,f);
    }
    fclose(f);
    uint32_t main=symbol("gMain"), sbp=symbol("gSaveBlock1Ptr");
    uint32_t sb=sbp?rd32(sbp):0, pc=0;
    core->readRegister(core,"pc",&pc);
    printf("STATE %s frame=%u pc=%08x callback2=%08x save_status=%u party=%u sb1=%08x map=%u,%u pos=%u,%u layout=%u\n",name,
           core->frameCounter(core),pc, main?rd32(main+4):0,
           symbol("gSaveFileStatus")?rd16(symbol("gSaveFileStatus")):999,
           symbol("gPlayerPartyCount")?rd8(symbol("gPlayerPartyCount")):999,
           sb,sb?rd8(sb+4):0,sb?rd8(sb+5):0,sb?rd16(sb):0,sb?rd16(sb+2):0,sb?rd16(sb+0x32):0);
    fflush(stdout);
}
static void export_save(const char *name) {
    void *save=NULL; size_t size=core->savedataClone(core,&save);
    char path[1024]; snprintf(path,sizeof(path),"%s/%s.sav",outdir,name);
    FILE *f=fopen(path,"wb");
    if(!f || !save || !size){fprintf(stderr,"save export failed\n");exit(2);}
    fwrite(save,1,size,f);fclose(f);free(save);
    printf("SAVE %s bytes=%zu\n",name,size);
}
static int is_map(unsigned group,unsigned num) {
    uint32_t a=symbol("gSaveBlock1Ptr"); if(!a)return 0;
    uint32_t sb=rd32(a); return sb && rd8(sb+4)==group && rd8(sb+5)==num;
}
static void save_from_menu(void) {
    press(8); frames(60,0); snapshot("04-start-menu");
    uint32_t acts=symbol("sCurrentStartMenuActions"), count=symbol("sNumStartMenuActions"), cursor=symbol("sStartMenuCursorPos");
    unsigned n=count?rd8(count):0, target=99;
    for(unsigned i=0;i<n && i<10;i++) if(rd8(acts+i)==5)target=i;
    printf("START_MENU count=%u cursor=%u save_slot=%u\n",n,cursor?rd8(cursor):99,target);
    if(target==99){check("native SAVE menu available",0);return;}
    for(unsigned i=0;i<12 && rd8(cursor)!=target;i++)press(128);
    press(1); frames(80,0); snapshot("05-save-prompt");
    for(unsigned i=0;i<4;i++){press(1);frames(150,0);}
    frames(180,0); snapshot("06-after-save"); export_save("fresh-career");
}
static int commands(const char *path) {
    FILE *f=fopen(path,"r");if(!f){perror(path);return 2;}
    char line[1024],cmd[100],arg[240];unsigned n,k,offset,width,expected;
    while(fgets(line,sizeof(line),f)) {
        if(line[0]=='#' || sscanf(line,"%99s",cmd)!=1)continue;
        if(sscanf(line,"frames %u %u",&n,&k)==2)frames(n,k);
        else if(sscanf(line,"press %u",&k)==1)press(k);
        else if(sscanf(line,"snap %239s",arg)==1)snapshot(arg);
        else if(sscanf(line,"save %239s",arg)==1)export_save(arg);
        else if(!strcmp(cmd,"reset")){core->reset(core);}
        else if(!strcmp(cmd,"native_save")){save_from_menu();}
        else if(sscanf(line,"map %u %u",&n,&k)==2)check("expected map",is_map(n,k));
        else if(sscanf(line,"expect %239s %u %u %u",arg,&offset,&width,&expected)==4) {
            uint32_t a=symbol(arg);unsigned value=width==1?rd8(a+offset):width==2?rd16(a+offset):rd32(a+offset);
            check(arg,a && value==expected);
        } else {fprintf(stderr,"Unknown command %s",line);fclose(f);return 2;}
    }
    fclose(f);return failed?1:0;
}
int main(int argc,char **argv) {
    if(argc<5){fprintf(stderr,"usage: smoke rom symbols output auto|commands [savefile|-] [citygroup citynum]\n");return 2;}
    outdir=argv[3];mkdir(outdir,0777);
    FILE *sf=fopen(argv[2],"r");if(!sf){perror(argv[2]);return 2;}
    char line[512],type,name[180];unsigned addr;
    while(fgets(line,sizeof(line),sf))if(sscanf(line,"%x %c %179s",&addr,&type,name)==3 && nsym<90000) {
        syms[nsym].addr=addr;strcpy(syms[nsym++].name,name);
    }
    fclose(sf);
    core=mCoreFind(argv[1]);
    if(!core || !core->init(core)){fprintf(stderr,"mGBA init failed\n");return 2;}
    mCoreInitConfig(core,NULL);
    struct mCoreOptions opts={0}; opts.useBios=false;opts.skipBios=true;opts.audioBuffers=1024;opts.sampleRate=32768;opts.mute=true;opts.volume=0;opts.logLevel=0;
    mCoreConfigLoadDefaults(&core->config,&opts);mCoreLoadConfig(core);
    core->setVideoBuffer(core,pixels,240);
    if(!mCoreLoadFile(core,argv[1])){fprintf(stderr,"ROM load failed\n");return 2;}
    if(argc>5 && strcmp(argv[5],"-") && !mCoreLoadSaveFile(core,argv[5],true)){fprintf(stderr,"save fixture load failed\n");return 2;}
    if(argc<=5 || !strcmp(argv[5],"-"))
    {
        // The native savedataClone interface requires an attached save backend.
        // Use an erased 128 KiB Flash fixture, not an in-memory-only emulator.
        char fixture[1024]; snprintf(fixture,sizeof(fixture),"%s/%s",outdir,"flash-backend.sav");
        FILE *fp=fopen(fixture,"wb");
        if(!fp){fprintf(stderr,"cannot create flash fixture\n");return 2;}
        unsigned char erased[4096];memset(erased,0xFF,sizeof(erased));
        for(int block=0;block<32;block++) if(fwrite(erased,1,sizeof(erased),fp)!=sizeof(erased)){fprintf(stderr,"flash fixture write failed\n");fclose(fp);return 2;}
        fclose(fp);
        if(!mCoreLoadSaveFile(core,fixture,true)){fprintf(stderr,"flash backend attach failed\n");return 2;}
        printf("TEST FLASH BACKEND: fresh erased 131072-byte save attached; runtime save/export still must pass.\n");
    }
    core->reset(core);
    if(strcmp(argv[4],"auto"))return commands(argv[4]);
    frames(300,0);snapshot("01-title");
    uint32_t title=symbol("Main_AscensionTitle"), main=symbol("gMain");
    check("native Shadow Lugia title callback",title && (rd32(main+4)&~1u)==(title&~1u));
    press(8);frames(150,0);snapshot("02-new-game-menu");
    press(1);frames(480,0);snapshot("03-new-career-city");
    unsigned group=argc>6?(unsigned)atoi(argv[6]):999, num=argc>7?(unsigned)atoi(argv[7]):999;
    int city=is_map(group,num);
    check("NEW GAME reaches Ascension without SELECT",city);
    check("native initial party has six members",symbol("gPlayerPartyCount") && rd8(symbol("gPlayerPartyCount"))==6);
    if(city) {
        save_from_menu();
        uint32_t sb=rd32(symbol("gSaveBlock1Ptr")),money=rd32(sb+0x490);
        core->reset(core);frames(300,0);press(8);frames(140,0);snapshot("07-continue-menu");
        press(1);frames(380,0);snapshot("08-continued-career");
        check("saved career returns to same city",is_map(group,num));
        check("saved party preserved",rd8(symbol("gPlayerPartyCount"))==6);
        sb=rd32(symbol("gSaveBlock1Ptr"));check("encrypted money unchanged after reload",rd32(sb+0x490)==money);
        core->reset(core);frames(300,0);press(8);frames(140,0);press(128);press(1);frames(120,0);snapshot("09-restart-warning");
        press(2);frames(180,0);snapshot("10-restart-canceled");
        export_save("after-canceled-restart");
    }
    printf("RESULT failures=%d; scope=boot/menu/fresh-career/save-smoke-only\n",failed);
    mCoreConfigDeinit(&core->config);core->deinit(core);
    return failed?1:0;
}
